import TeamcityLogo from '@jetbrains/logos/teamcity/teamcity.svg'
import {H1} from '@jetbrains/ring-ui-built/components/heading/heading'
import {baseUri} from '@jetbrains/teamcity-ui'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import {memo} from 'react'

import BuildLineLayout from '../../../containers/BuildLineLayout'
import BuildsFetcher from '../../../containers/BuildsFetcher'
import Builds from '../Builds/Builds.container'

import styles from './BuildsTvMode.module.css'

type Props = {
  locator: string | null
  title?: string | null
  showLogo: boolean
  showDropDowns: boolean
  showExactStartDate: boolean
  updatePeriod: number
}

function BuildsTvMode({
  locator,
  title,
  showLogo,
  showDropDowns,
  showExactStartDate,
  updatePeriod,
}: Props) {
  const classes = classNames(styles.buildsTvMode, {
    [styles.hideDropDowns]: !showDropDowns,
  })

  return (
    <div className={classes}>
      <div className={styles.title}>
        {showLogo && (
          <IconButton
            title="TeamCity"
            className={styles.titleIcon}
            icon={TeamcityLogo}
            href={baseUri}
          />
        )}
        {title != null && <H1 className={styles.titleText}>{title}</H1>}
      </div>
      <BuildsFetcher
        locator={locator}
        updatePeriod={updatePeriod}
        withQueued
        withRunning
        withBuildDetails
      >
        <BuildLineLayout showExactDuration={showExactStartDate} showPath={false}>
          <Builds withLoader />
        </BuildLineLayout>
      </BuildsFetcher>
    </div>
  )
}

export default memo(BuildsTvMode)
