import debounce from 'just-debounce-it'

import Button from '@jetbrains/ring-ui-built/components/button/button'
import {Size} from '@jetbrains/ring-ui-built/components/input/input'
import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import {objectKeys, resolveRelative} from '@jetbrains/teamcity-ui/dist/utils'
import classNames from 'classnames'
import * as React from 'react'
import {Suspense} from 'react'
import {EntryPointContainer} from 'react-relay'
import type {PreloadedEntryPoint} from 'react-relay/relay-hooks/EntryPointTypes'

import {LocatorContext} from '../../../contexts/locator'
import {useQueryParam} from '../../../hooks/routes'
import {
  getBuildsBackgroundLoading,
  getBuildsLoading,
  getBuildsLocatorWithPage,
  getIsUpdating,
} from '../../../selectors'
import type {BuildTypeId, ProjectOrBuildTypeNode} from '../../../types'
import {noop} from '../../../utils/empty'
import {cmdOrCtrlPlus} from '../../../utils/keys'
import {GlobalSearchKind} from '../../packages/Shortcuts/Shortcuts.types'
import BuildStateFilter from '../BuildStateFilter/BuildStateFilter'
import {BuildState, StateOptions} from '../BuildStateFilter/BuildStateFilter.consts'
import {buildsTvModeDefaultUrlParams} from '../BuildsTvMode/BuildsTvMode.container'
import {usePage} from '../Pager/Pager.hooks'
import {ProjectBuildTypeSelect} from '../ProjectBuildTypeSelect/ProjectBuildTypeSelect'
import SearchInput from '../SearchInput/SearchInput'
import type {TagsFiltersContainerComponent} from '../TagsList/TagsFilters'

import styles from './BuildsFilters.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

const AGENT_PATTERN_DEBOUNCE = 500 // ms

type DefaultProps = {
  locator: string | null | undefined
  useRawLocator: boolean
  showUpdateResults: boolean
  changeLocator: (arg0: string) => unknown
  toggleAdvancedMode: () => unknown
  changeProjectBuildtypeFilter: (arg0: ProjectOrBuildTypeNode) => unknown
  updateResults: () => unknown
  setTagFilter: (arg0: string | null | undefined) => unknown
}
export type Props = DefaultProps & {
  className?: string
  projectBuildtypeFilter?: ProjectOrBuildTypeNode | null | undefined
  tag?: string | null | undefined
  agentPattern?: string | null | undefined
  buildNamePattern?: string | null | undefined
  disableAdvancedMode?: boolean
  withProjectBuildtypeFilter?: boolean
  withStateFilter?: boolean
  withRunningAndQueued?: boolean | null
  withTagFilter?: boolean
  withAgentPatternFilter?: boolean
  withBuildNamePatternFilter?: boolean
  buildTypeId?: BuildTypeId
  locatorHelpUrl?: string | null | undefined
  hide?: boolean
  withBuildsInNewWindowLink?: boolean
  filterBuildtypes?: boolean
  includedBuildTypes?: ReadonlyArray<BuildTypeId> | null | undefined
  hint?: string | null | undefined
  hintAction?: string | null | undefined
  withPager?: boolean
  setAgentPatternFilter: (arg0: string | null | undefined) => unknown
  setBuildNamePatternFilter: (arg0: string | null | undefined) => unknown
  tagsFiltersEntryPoint?: PreloadedEntryPoint<TagsFiltersContainerComponent>
}
type State = {
  locator?: string | null | undefined
  prevLocator?: string | null | undefined
  agentPattern?: string | null | undefined
  buildNamePattern?: string | null | undefined
  prevAgentPattern?: string | null | undefined
  showAllBuildtypes?: boolean
}

type FilterButtonsGroupProps = {
  withRunningAndQueued?: boolean | null
  withPager?: boolean
}

const STATES_WITH_OPTIONSL = objectKeys(StateOptions)
const STATES_WITHOUT_OPTIONSL = objectKeys(StateOptions).filter(
  key => key !== BuildState.QUEUED && key !== BuildState.RUNNING,
)

const FilterButtonsGroup = React.memo(function FilterButtonsGroup({
  withRunningAndQueued,
  withPager,
}: FilterButtonsGroupProps) {
  const activeStateQueryParam = useQueryParam('state') ?? ''
  const activeState = (activeStateQueryParam as BuildState) || BuildState.ALL
  const states = withRunningAndQueued === true ? STATES_WITH_OPTIONSL : STATES_WITHOUT_OPTIONSL

  const locator = React.useContext(LocatorContext)
  const page = usePage()
  const locatorWithPage = useAppSelector(
    state => locator && (withPager ? getBuildsLocatorWithPage(state, locator, page) : locator),
  )
  const isLoading = useAppSelector(
    state =>
      getBuildsLoading(state, locatorWithPage) &&
      !getIsUpdating(state) &&
      !getBuildsBackgroundLoading(state, locatorWithPage),
  )

  return (
    <BuildStateFilter activeState={activeState} states={states} isLoading={isLoading} withLink />
  )
})
FilterButtonsGroup.displayName = 'FilterButtonsGroup'

const UpdateResultButton = React.memo(function UpdateResultButton() {
  const isUpdating = useAppSelector(getIsUpdating)
  const locator = React.useContext(LocatorContext)
  const showLoader = useAppSelector(state => !isUpdating && getBuildsLoading(state, locator))
  const classes = classNames(styles.update, {
    [styles.showLoader]: showLoader,
  })
  return (
    <span className={classes}>
      <span className={styles.loaderBlock}>
        <LoaderInline className={styles.loader} />
        {'Loading...'}
      </span>
      <Button type="submit" loader={isUpdating} className={styles.updateButton}>
        {'Update results'}
      </Button>
    </span>
  )
})

const showLocatorInput = ({useRawLocator, disableAdvancedMode}: Props) =>
  useRawLocator && disableAdvancedMode !== true

class BuildsFilters extends React.Component<Props, State> {
  static defaultProps: DefaultProps = {
    locator: null,
    useRawLocator: false,
    showUpdateResults: false,
    changeLocator: noop,
    toggleAdvancedMode: noop,
    changeProjectBuildtypeFilter: noop,
    updateResults: noop,
    setTagFilter: noop,
  }

  static getDerivedStateFromProps(
    {locator, buildNamePattern, agentPattern}: Props,
    {prevLocator, prevAgentPattern}: State,
  ): State | null | undefined {
    if (locator !== prevLocator || agentPattern !== prevAgentPattern) {
      return {
        locator,
        prevLocator: locator,
        agentPattern,
        prevAgentPattern: agentPattern,
        buildNamePattern,
      }
    }

    return null
  }

  state: State = Object.freeze({})
  locator: React.ElementRef<'input'> | null | undefined

  setAgentPatternFilter: (pattern: string) => void = debounce((pattern: string) => {
    const {agentPattern, setAgentPatternFilter} = this.props

    if (pattern !== agentPattern) {
      setAgentPatternFilter(pattern)
    }
  }, AGENT_PATTERN_DEBOUNCE)

  setBuildNamePatternFilter: (pattern: string) => void = debounce((pattern: string) => {
    const {agentPattern, setBuildNamePatternFilter} = this.props

    if (pattern !== agentPattern) {
      setBuildNamePatternFilter(pattern)
    }
  }, AGENT_PATTERN_DEBOUNCE)

  handleProjectSelect: (arg0: ProjectOrBuildTypeNode | null | undefined) => void = item => {
    const {projectBuildtypeFilter, changeProjectBuildtypeFilter} = this.props

    if (
      item != null &&
      (item.nodeType !== projectBuildtypeFilter?.nodeType ||
        (projectBuildtypeFilter?.nodeType !== 'all' && item.id !== projectBuildtypeFilter?.id))
    ) {
      changeProjectBuildtypeFilter(item)
    }
  }

  handleShowAllBuildtypes: () => void = () => {
    this.setState({
      showAllBuildtypes: true,
    })
  }

  locatorRef: React.Ref<HTMLInputElement> = el => {
    this.locator = el
  }

  handleSubmit: (arg0: React.SyntheticEvent) => void = e => {
    e.preventDefault()
    const {locator, agentPattern} = this.state

    if (this.props.useRawLocator && locator != null && locator !== this.props.locator) {
      this.props.changeLocator(locator)
    } else if (!this.props.useRawLocator && agentPattern !== this.props.agentPattern) {
      this.props.setAgentPatternFilter(agentPattern)
    } else {
      this.props.updateResults()
    }
  }

  handleLocatorInput: (event: React.ChangeEvent<HTMLInputElement>) => void = e => {
    this.setState({
      locator: e.currentTarget.value,
    })
  }

  handleLocatorClear: () => void = () => {
    this.setState({
      locator: '',
    })
  }

  handleAgentPatternInput: (event: React.ChangeEvent<HTMLInputElement>) => void = e => {
    const agentPattern = e.currentTarget.value
    this.setState({
      agentPattern,
    })
    this.setAgentPatternFilter(agentPattern)
  }

  handleBuildNamePatternInput: (
    event: React.ChangeEvent<HTMLInputElement> | React.MouseEvent<HTMLButtonElement>,
  ) => void = e => {
    const buildNamePattern = e.currentTarget.value
    this.setState({
      buildNamePattern,
    })
    this.setBuildNamePatternFilter(buildNamePattern)
  }

  componentDidMount() {
    if (showLocatorInput(this.props)) {
      this.locator?.select()
    }
  }

  componentDidUpdate(prevProps: Props) {
    if (showLocatorInput(this.props) && !showLocatorInput(prevProps)) {
      this.locator?.select()
    }
  }

  handleReset = () => {
    this.props.setTagFilter(null)
  }

  getOpenInNewWindowLinkContent(locator: string): React.ReactNode {
    return (
      <IconButton
        icon="new-window"
        className={styles.newWindowLink}
        href={resolveRelative(
          `/builds.html?locator=${encodeURIComponent(
            locator,
          )}&${buildsTvModeDefaultUrlParams.toString()}`,
        )}
        target="_blank"
        rel="noreferrer"
        title="Open in a new tab"
      />
    )
  }

  render(): React.ReactNode {
    const {
      className,
      hide,
      locator,
      useRawLocator,
      tag,
      withProjectBuildtypeFilter,
      withStateFilter,
      withRunningAndQueued,
      withTagFilter,
      withAgentPatternFilter,
      withBuildNamePatternFilter,
      withBuildsInNewWindowLink,
      buildTypeId,
      projectBuildtypeFilter,
      disableAdvancedMode,
      locatorHelpUrl,
      filterBuildtypes,
      includedBuildTypes,
      hint,
      hintAction,
      showUpdateResults,
      toggleAdvancedMode,
      withPager,
      tagsFiltersEntryPoint,
    } = this.props
    const allItemName = '<All projects and build configurations>'
    return (
      hide !== true && (
        <form className={className} onSubmit={this.handleSubmit}>
          <div className={styles.row}>
            {showLocatorInput(this.props) ? (
              <span className={styles.locator}>
                <SearchInput
                  placeholder={'Locator'}
                  value={this.state.locator || ''}
                  onChange={this.handleLocatorInput}
                  inputRef={this.locatorRef}
                  spellCheck={false}
                  helpUrl={locatorHelpUrl}
                />
              </span>
            ) : (
              <span className={styles.controls}>
                {withStateFilter === true && (
                  <FilterButtonsGroup
                    withPager={withPager}
                    withRunningAndQueued={withRunningAndQueued}
                  />
                )}
                {withAgentPatternFilter && (
                  <SearchInput
                    size={Size.M}
                    className={styles.agentPattern}
                    type="search"
                    placeholder="Filter by agent name"
                    value={this.state.agentPattern || ''}
                    onChange={this.handleAgentPatternInput}
                    spellCheck={false}
                  />
                )}
                {withBuildNamePatternFilter && !withAgentPatternFilter && (
                  <SearchInput
                    size={Size.M}
                    className={styles.agentPattern}
                    searchKind={GlobalSearchKind.DEPENDENCIES_SEARCH}
                    type="search"
                    placeholder={`Search (${cmdOrCtrlPlus}K)`}
                    value={this.state.buildNamePattern || ''}
                    onChange={this.handleBuildNamePatternInput}
                    onClear={this.handleBuildNamePatternInput}
                    spellCheck={false}
                  />
                )}
                {withProjectBuildtypeFilter === true &&
                  (filterBuildtypes !== true ||
                    (includedBuildTypes && includedBuildTypes.length > 0)) && (
                    <ProjectBuildTypeSelect
                      className={styles.projects}
                      allItemName={allItemName}
                      allItemSelectable
                      includedBuildTypes={
                        this.state.showAllBuildtypes === true ? undefined : includedBuildTypes
                      }
                      expandAll
                      selected={projectBuildtypeFilter}
                      hint={hint}
                      hintAction={hintAction}
                      onSelect={this.handleProjectSelect}
                      onHintAction={this.handleShowAllBuildtypes}
                    />
                  )}
              </span>
            )}
            {disableAdvancedMode === true || (
              <Button onClick={toggleAdvancedMode} className={styles.toggle}>
                {useRawLocator ? 'Switch back to filters' : 'Show advanced search'}
              </Button>
            )}
            {showUpdateResults && <UpdateResultButton />}
          </div>
          <div className={styles.row}>
            {withTagFilter === true && buildTypeId != null && (
              <div className={styles.tagsFiltersWrapper}>
                {tagsFiltersEntryPoint != null && (
                  <Suspense>
                    <EntryPointContainer
                      entryPointReference={tagsFiltersEntryPoint}
                      props={{
                        buildTypeId,
                        selected: tag,
                        onReset: this.handleReset,
                      }}
                    />
                  </Suspense>
                )}
              </div>
            )}
            {withBuildsInNewWindowLink === true &&
              locator != null &&
              this.getOpenInNewWindowLinkContent(locator)}
          </div>
        </form>
      )
    )
  }
}

export default BuildsFilters
