import compose from 'lodash/flowRight'
import {connect} from 'react-redux'
import type {PreloadedEntryPoint} from 'react-relay/relay-hooks/EntryPointTypes'
import * as Redux from 'redux'

import {updateResults} from '../../../actions'
import type {AppDispatch} from '../../../actions/types'
import {withLocator} from '../../../contexts/locator'
import {withUpdateResults} from '../../../contexts/update'
import withHook from '../../../hocs/withHook'
import {
  useBooleanQueryParamState,
  useQueryParams,
  useSetQueryParam,
  useSetQueryParams,
} from '../../../hooks/routes'
import type {State} from '../../../reducers/types'
import {getBuildTypesFromLoadedBuild, getBuildsLocatorWithPage} from '../../../selectors'
import type {BuildTypeId} from '../../../types'
import {toBuildTypeId, toProjectId, getProjectBuildTypeFilter} from '../../../types'
import {usePage} from '../Pager/Pager.hooks'
import {getPager} from '../Pager/Pager.selectors'
import {PagerGroup} from '../Pager/Pager.types'
import type {TagsFiltersContainerComponent} from '../TagsList/TagsFilters'

import BuildsFilters from './BuildsFilters'

type OwnProps = {
  filterBuildtypes?: boolean
  withPager?: boolean
  className?: string
  disableAdvancedMode?: boolean
  withProjectBuildtypeFilter?: boolean
  withStateFilter?: boolean
  withTagFilter?: boolean
  withAgentPatternFilter?: boolean
  withBuildNamePatternFilter?: boolean
  buildTypeId?: BuildTypeId
  locatorHelpUrl?: string | null | undefined
  hide?: boolean
  withBuildsInNewWindowLink?: boolean
  hintAction?: string
  showUpdateResults?: boolean
  withRunningAndQueued?: boolean | null | undefined
  tagsFiltersEntryPoint?: PreloadedEntryPoint<TagsFiltersContainerComponent>
}
type ReduxOwnProps = OwnProps & {
  locator: string | null | undefined
  updateResults: () => unknown
  page: number
}
type StateProps = {
  includedBuildTypes: ReadonlyArray<BuildTypeId> | null | undefined
  hint: string | null | undefined
  hintAction: string | null | undefined
}
type ActionProps = {
  updateResults: () => unknown
}
type Props = ReduxOwnProps & StateProps & ActionProps

const mapStateToProps = (state: State, props: ReduxOwnProps): StateProps => {
  const {locator, filterBuildtypes, withPager, page} = props
  const pager = getPager(state, PagerGroup.BUILD)
  const locatorWithPage =
    locator && (withPager ? getBuildsLocatorWithPage(state, locator, page) : locator)
  const includedBuildTypes =
    filterBuildtypes === true ? getBuildTypesFromLoadedBuild(state, locatorWithPage) : null
  const numberOfBuildTypes = includedBuildTypes ? includedBuildTypes.length : 0
  const showHint = filterBuildtypes === true && pager.total > pager.pageSize
  return {
    includedBuildTypes,
    hint: showHint
      ? `Showing ${numberOfBuildTypes} configuration${
          numberOfBuildTypes === 1 ? '' : 's'
        } from loaded builds.`
      : null,
    hintAction: showHint ? 'Show all' : null,
  }
}

const mapDispatchToProps = (dispatch: AppDispatch, props: ReduxOwnProps): ActionProps =>
  Redux.bindActionCreators(
    {
      updateResults: updateResults(props.updateResults),
    },
    dispatch,
  )

function BuildsFiltersContainer(props: Props) {
  const {withBuildNamePatternFilter} = props
  const {
    tag,
    projectId,
    buildTypeId: buildTypeIdString,
    'agent-name-pattern': agentPattern,
    'build-name-pattern': buildNamePattern,
  } = useQueryParams()
  const buildTypeId = buildTypeIdString != null ? toBuildTypeId(buildTypeIdString) : undefined
  const [useRawLocator, setUseRawLocator] = useBooleanQueryParamState('use-raw-locator')
  const setLocator = useSetQueryParam('locator')
  const setQueryParams = useSetQueryParams()

  return (
    <BuildsFilters
      {...props}
      tag={useRawLocator ? null : tag}
      useRawLocator={useRawLocator}
      projectBuildtypeFilter={
        useRawLocator
          ? null
          : getProjectBuildTypeFilter({
              projectId: projectId != null ? toProjectId(projectId) : null,
              buildTypeId,
            })
      }
      agentPattern={useRawLocator ? null : agentPattern}
      buildNamePattern={withBuildNamePatternFilter ? buildNamePattern : null}
      setTagFilter={value => setQueryParams({page: '1', tag: value})}
      toggleAdvancedMode={() => setUseRawLocator(!useRawLocator)}
      changeLocator={setLocator}
      changeProjectBuildtypeFilter={node =>
        setQueryParams({
          page: '1',
          projectId: node.nodeType === 'project' ? node.id : null,
          buildTypeId: node.nodeType === 'bt' ? node.id : null,
        })
      }
      setBuildNamePatternFilter={value => setQueryParams({page: '1', 'build-name-pattern': value})}
      setAgentPatternFilter={value => setQueryParams({page: '1', 'agent-name-pattern': value})}
    />
  )
}

export default compose(
  withLocator,
  withUpdateResults(),
  withHook(() => ({page: usePage()})),
  connect(mapStateToProps, mapDispatchToProps),
)(BuildsFiltersContainer)
